mapper.select:
        select
        videos.*,
        videoType.type_name,
        videoUser.nick_name,
        videoUser.head_img,
        COALESCE(videoCommentCount.comment_count, 0) AS comment_count
        from videos videos
        left join video_type videoType on videos.type_id = videoType.id
		left join video_user videoUser on videos.user_id = videoUser.id
        LEFT JOIN (
        SELECT videos_id, COUNT(*) AS comment_count
        FROM video_comment
        GROUP BY  videos_id
        ) AS videoCommentCount ON videos.id = videoCommentCount.videos_id

            and videos.id = #{id}
            and videos.video_name like concat('%',#{videoName},'%') or videos.video_info like concat('%',#{videoName},'%')
            and videos.video_info like concat('%',#{videoName},'%')
            and videos.banner_img = #{bannerImg}
            and videos.video_url = #{videoUrl}
            and videos.create_time = #{createTime}
            and videos.type_id = #{typeId}
            and videos.click_num = #{clickNum}
            and videos.collect_num = #{collectNum}
            and videos.user_id = #{userId}
            and videos.status = #{status}
            and videoType.type_name like concat('%',#{typeName},'%')
            and videoUser.nick_name like concat('%',#{nickName},'%')
            and videoUser.head_img = #{headImg}

        order by collect_num,click_num,comment_count desc

            limit #{current},#{pageSize}

        select count(*) from videos videos
        left join video_type videoType on videos.type_id = videoType.id
		left join video_user videoUser on videos.user_id = videoUser.id

            and videos.id = #{id}
            and videos.video_name like concat('%',#{videoName},'%')
            and videos.video_info like concat('%',#{videoName},'%')
            and videos.banner_img = #{bannerImg}
            and videos.video_url = #{videoUrl}
            and videos.create_time = #{createTime}
            and videos.type_id = #{typeId}
            and videos.click_num = #{clickNum}
            and videos.collect_num = #{collectNum}
            and videos.user_id = #{userId}
            and videos.status = #{status}
            and videoType.type_name like concat('%',#{typeName},'%')
            and videoUser.nick_name like concat('%',#{nickName},'%')
            and videoUser.head_img = #{headImg}
